#include "csb_hint_oracle_graphics_surface.h"
#include <stdlib.h>
#include <string.h>
void csb_hint_oracle_graphics_surface_init(CSB_HintOracleGraphicsSurface *s){if(s){memset(s,0,sizeof(*s));csb_hint_oracle_dat_real_cache_init(&s->source);}}
void csb_hint_oracle_graphics_surface_free(CSB_HintOracleGraphicsSurface *s){if(s){free(s->font_pixels);free(s->pixels);csb_hint_oracle_dat_real_cache_free(&s->source);memset(s,0,sizeof(*s));}}
int csb_hint_oracle_graphics_surface_load(CSB_HintOracleGraphicsSurface *s,const char *dir,int depth,const char *md5){const uint8_t *img,*font,*pal;size_t ni,nf,np;int rc;if(!s)return -1;csb_hint_oracle_graphics_surface_free(s);csb_hint_oracle_graphics_surface_init(s);rc=csb_hint_oracle_dat_real_scan_and_load(dir,depth,md5,&s->source);if(rc)return rc;if(csb_hint_oracle_dat_get_segment(&s->source.archive,1,&img,&ni)||csb_hint_oracle_dat_get_segment(&s->source.archive,2,&font,&nf)||csb_hint_oracle_dat_get_segment(&s->source.archive,3,&pal,&np))goto bad;s->pixels=(uint8_t*)malloc(CSB_HINT_ORACLE_GRAPHICS_SURFACE_WIDTH*CSB_HINT_ORACLE_GRAPHICS_SURFACE_HEIGHT);s->font_pixels=(uint8_t*)malloc(CSB_HINT_ORACLE_FONT_SURFACE_WIDTH*CSB_HINT_ORACLE_FONT_SURFACE_HEIGHT);if(!s->pixels||!s->font_pixels)goto bad;if(!csb_hint_oracle_dat_img2_decode(img,ni,&s->width,&s->height,s->pixels,64000,NULL)||s->width!=320||s->height!=200||!csb_hint_oracle_dat_img2_decode(font,nf,&s->font_width,&s->font_height,s->font_pixels,CSB_HINT_ORACLE_FONT_SURFACE_WIDTH*CSB_HINT_ORACLE_FONT_SURFACE_HEIGHT,NULL)||s->font_width!=CSB_HINT_ORACLE_FONT_SURFACE_WIDTH||s->font_height!=CSB_HINT_ORACLE_FONT_SURFACE_HEIGHT||!csb_hint_oracle_dat_palette_decode(pal,np,s->rgb4))goto bad;return 0;bad:csb_hint_oracle_graphics_surface_free(s);return -4;}
int csb_hint_oracle_graphics_surface_blit_st_text(const CSB_HintOracleGraphicsSurface *s,uint8_t *f,size_t n,int x,int y,const char *t){int px,py;if(!s||!f||!t||!s->font_pixels||s->font_width!=256u||s->font_height!=27u||n<64000u)return 0;for(;*t;++t,x+=9){unsigned char c=(unsigned char)*t;unsigned char g;if(c<' '||c>0x7fu)continue;g=(unsigned char)(c-' ');if(!g)continue;for(py=0;py<9;++py)for(px=0;px<8;++px){int dx=x+px,dy=y+py;uint8_t p=s->font_pixels[((size_t)(g>>5u)*9u+(size_t)py)*256u+((size_t)(g&31u)*8u+(size_t)px)];if(dx>=0&&dx<320&&dy>=0&&dy<200&&p!=12u)f[(size_t)dy*320u+(size_t)dx]=p;}}return 1;}
